INSERT INTO `email_templates` (`id`, `title`, `message`, `status`) VALUES
(1, 'Confirmar registro', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Registro de cuenta</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ff4800\" height=\"50\" style=\"background: #ff4800;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><img alt=\"\" src=\"https://shortpaid.com/assets/methods/foxchanger.png\" style=\"display: block;\" width=\"163\" /></strong></p>\r\n						</td>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Estimado/a [NAME]<br />\r\n						<br />\r\n						Gracias por crear una cuenta en [SITE_NAME]. Haga clic en el enlace a continuaci&oacute;n para validar su direcci&oacute;n de correo electr&oacute;nico y activar su cuenta.</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #ff4800; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #ff4800; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[CHECK_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #ff4800; border-radius: 4px;\" target=\"_blank\">Confirmar correo</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #ff4800; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"color:#939aa4; font-family:Arial, sans-serif, Helvetica; font-size:13px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:-webkit-center; text-transform:none; white-space:normal; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; background-color:#ebedef; text-decoration-style:initial; text-decoration-color:initial; vertical-align:inherit\">Tienes alguna pregunta?&nbsp;</font><font style=\"color:#939aa4; font-family:Arial, sans-serif, Helvetica; font-size:13px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:-webkit-center; text-transform:none; white-space:normal; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; background-color:#ebedef; text-decoration-style:initial; text-decoration-color:initial; vertical-align:inherit\">Escriba al Servicio de soporte.</font><br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(2, 'Inicio de sesión', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Inicio de sesi&oacute;n en tu cuenta</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ff4800\" height=\"50\" style=\"background: #ff4800;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><img alt=\"\" src=\"https://shortpaid.com/assets/methods/foxchanger.png\" style=\"display: block;\" width=\"163\" /></strong></p>\r\n						</td>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Querido/a, [NAME]!</p>\r\n\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Usted u otra persona ha iniciado sesi&oacute;n en su cuenta. Si no intent&oacute; acceder a su cuenta y cree que era otra persona, es mejor cambiar su contrase&ntilde;a para acceder a la cuenta.</p>\r\n\r\n						<p style=\"color: #303030; font: 18px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\"><strong>Direcci&oacute;n IP&nbsp;[IP_ADDRESS]</strong></p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #ff4800; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #ff4800; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[ACCOUNT_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #ff4800; border-radius: 4px;\" target=\"_blank\">Mi cuenta</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #ff4800; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\">Tienes alguna pregunta? Escriba al Servicio de soporte.<br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(3, 'Restablecer contraseña', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n    @media only screen and (min-width: 640px) {\r\n      *[class].wrapper { width: 480px !important; }\r\n      *[class].wrapper__indent { width: 60px !important; }\r\n    }\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Restablecer contrase&ntilde;a</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ff4800\" height=\"50\" style=\"background: #ff4800;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"163\" /></strong></p>\r\n						</td>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Ha solicitado restablecer la contrase&ntilde;a en [SITE_NAME]</p>\r\n\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Su nueva contrase&ntilde;a es:<strong> [PASSWORD]</strong></p>\r\n\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">&nbsp;Inicie sesi&oacute;n y cambie la contrase&ntilde;a inmediatamente.</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #882db6; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #882db6; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[ACCOUNT_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #ff4800; border-radius: 4px;\" target=\"_blank\">Mi cuenta</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"color:#939aa4; font-family:Arial, sans-serif, Helvetica; font-size:13px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:-webkit-center; text-transform:none; white-space:normal; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; background-color:#ebedef; text-decoration-style:initial; text-decoration-color:initial; vertical-align:inherit\"><font style=\"vertical-align:inherit\"><font style=\"vertical-align:inherit\"><font style=\"vertical-align:inherit\">Tienes alguna pregunta?&nbsp;</font></font></font><font style=\"vertical-align:inherit\"><font style=\"vertical-align:inherit\"><font style=\"vertical-align:inherit\">Escriba al Servicio de soporte.</font></font></font></font><br style=\"color:#939aa4; font-family:Arial, sans-serif, Helvetica; font-size:13px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:-webkit-center; text-transform:none; white-space:normal; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; background-color:#ebedef; text-decoration-style:initial; text-decoration-color:initial\" />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', '1'),
(4, 'Boleto Creado', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Mensaje de soporte</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#882db6\" height=\"50\" style=\"background: #882db6;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Nuevo boleto</font></font></strong></p>\r\n						</td>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Estimado [NAME]! </font></font><br />\r\n						<br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Para usted, se ha creado un nuevo boleto&nbsp;en el sitio [SITE_NAME].</font></font></p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[TICKET_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #c42cee; border-radius: 4px;\" target=\"_blank\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Leer&nbsp;mensaje</font></font></a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Tienes alguna pregunta? </font><font style=\"vertical-align: inherit;\">Escriba al Servicio de soporte. </font></font><br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">[SITE_NAME]</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(5, 'Nuevo comentario en boleto', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Mensaje de soporte</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#882db6\" height=\"50\" style=\"background: #882db6;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Nuevo comentario</font></font></strong></p>\r\n						</td>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Estimado [NAME]! </font></font><br />\r\n						<br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Hay un nuevo comentario disponible para el boleto [CODE_TICKET].</font></font></p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[TICKET_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #c42cee; border-radius: 4px;\" target=\"_blank\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Leer mensaje</font></font></a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Tienes alguna pregunta? </font><font style=\"vertical-align: inherit;\">Escriba al Servicio de soporte. </font></font><br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">[SITE_NAME]</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
