tical-align: inherit;\">Tienes alguna pregunta? </font><font style=\"vertical-align: inherit;\">Escriba al Servicio de soporte. </font></font><br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">[SITE_NAME]</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(13, 'Nuevo comentario para disputa', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Estado de disputa</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#882db6\" height=\"50\" style=\"background: #882db6;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong>Nuevo comentario para disputa</strong></p>\r\n						</td>\r\n						<td style=\"background: #882db6;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Querido/a [NAME]!<br />\r\n						<br />\r\n						Se agreg&oacute; un nuevo comentario para el ID de disputa&nbsp;[ID_DISPUTE]. Puede leerlo despu&eacute;s de iniciar sesi&oacute;n en su cuenta..</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[SITE_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #c42cee; border-radius: 4px;\" target=\"_blank\">Mi&nbsp;cuenta</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"color:#939aa4; font-family:Arial, sans-serif, Helvetica; font-size:13px; font-style:normal; font-variant-ligatures:normal; font-variant-caps:normal; font-weight:400; letter-spacing:normal; orphans:2; text-align:-webkit-center; text-transform:none; white-space:normal; widows:2; word-spacing:0px; -webkit-text-stroke-width:0px; background-color:#ebedef; text-decoration-style:initial; text-decoration-color:initial; vertical-align:inherit\"><font style=\"vertical-align:inherit\">Tienes alguna pregunta?&nbsp;</font><font style=\"vertical-align:inherit\">Escriba al Servicio de soporte.</font></font><br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(14, 'Claim opened!', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Dispute status</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://justwallet.pw/themes/default/img/logo.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ffc107\" height=\"50\" style=\"background: #ffc107;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong>Claim opened!</strong></p>\r\n						</td>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Dear [NAME]!<br />\r\n						<br />\r\n						Your dispute ID [ID_DISPUTE] was transferred to the claim!</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[SITE_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #28a745; border-radius: 4px;\" target=\"_blank\">My account</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\">Have a questions? Write to the Support Service.<br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(15, 'Claim rejected', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Dispute status</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://justwallet.pw/themes/default/img/logo.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ffc107\" height=\"50\" style=\"background: #ffc107;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong>Claim rejected</strong></p>\r\n						</td>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Dear [NAME]!<br />\r\n						<br />\r\n						After a thorough analysis of the evidence provided by ID [ID_DISPUTE], we have completed the investigation and decided in favor of the seller.</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[SITE_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #28a745; border-radius: 4px;\" target=\"_blank\">My account</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\">Have a questions? Write to the Support Service.<br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(18, 'Documentos Recibidos', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Estado de la cuenta</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ff4800\" height=\"50\" style=\"background: #ff4800;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"163\" /></strong></p>\r\n						</td>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Estimado [NAME]! </font></font><br />\r\n						&nbsp;</p>\r\n\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">&iexcl;Su solicitud de verificaci&oacute;n extendida ha sido recibida con &eacute;xito! Revisaremos sus documentos dentro de 1-2&nbsp;d&iacute;as h&aacute;biles. Aunque este proceso no suele tardar m&aacute;s de 5 horas.</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #ff4800;; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #ff4800;; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[SITE_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #ff4800;; border-radius: 4px;\" target=\"_blank\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Mi cuenta</font></font></a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #ff4800;; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Tienes alguna pregunta? </font><font style=\"vertical-align: inherit;\">Escriba al Servicio de soporte. </font></font><br />\r\n						<font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">[SITE_NAME]</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(21, 'Claim satisfied', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\">Dispute status</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n						<td align=\"center\" height=\"70\" style=\"border-bottom: 1px solid #wwwwww;\" valign=\"middle\"><a alias=\"site_logo\" href=\"#\" target=\"_blank\"><img alt=\"\" src=\"https://justwallet.pw/themes/default/img/logo.png\" style=\"display: block;\" width=\"200\" /> </a></td>\r\n						<td class=\"wrapper__indent\" style=\"border-bottom: 1px solid #wwwwww;\" width=\"30\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ffc107\" height=\"50\" style=\"background: #ffc107;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong>Claim satisfied</strong></p>\r\n						</td>\r\n						<td style=\"background: #ffc107;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\">Dear [NAME]!<br />\r\n						<br />\r\n						After a thorough analysis of the evidence provided in the dispute ID [ID_DISPUTE], we completed the investigation and decided in favor of the sender of payment. Money was returned by transaction ID [ID_TRANSACTION].</p>\r\n						</td>\r\n						<td>&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">\r\n						<p align=\"center\" style=\"margin: 10px 0 25px;\"><a alias=\"button\" href=\"[SITE_LINK]\" style=\"text-decoration: none; font: 17px/40px Helvetica, Arial, sans-serif; color: #ffffff; display: block; width: 225px; background: #28a745; border-radius: 4px;\" target=\"_blank\">My account</a></p>\r\n						</td>\r\n						<td style=\"border-top: 0px solid #dee0e1; \">&nbsp;</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/20px Arial, sans-serif, Helvetica; color: #939aa4; margin: 20px 0 0;\">Have a questions? Write to the Support Service.<br />\r\n						[SITE_NAME]</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<!--// 100% body table -->', '1'),
(25, 'Ha enviado un pago', '<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n<title></title>\r\n<style type=\"text/css\">a:hover { text-decoration: underline !important; }\r\n\r\n		@media only screen and (min-width: 640px) {\r\n    	*[class].wrapper { width: 480px !important; }\r\n    	*[class].wrapper__indent { width: 60px !important; }\r\n		}\r\n</style>\r\n<table bgcolor=\"#ebedef\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td align=\"center\" height=\"45\" valign=\"middle\">\r\n						<p style=\"font: 13px/24px Arial, sans-serif, Helvetica; color: #939aa4; margin: 0px;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Estado de la transacci&oacute;n</font></font></p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n\r\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"wrapper\" style=\"background-color: #ffffff; border: 1px solid #c8cace; border-radius: 4px; margin: auto;\" width=\"480\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n						<td align=\"center\" bgcolor=\"#ff4800\" height=\"50\" style=\"background: #ff4800;\">\r\n						<p style=\"font: 17px/20px Helvetica, Arial, sans-serif; color: #ffffff;\"><strong><img alt=\"\" src=\"https://foxchanger.com/assets/themes/account/img/Foxchanger.png\" style=\"display: block;\" width=\"163\" /></strong></p>\r\n						</td>\r\n						<td style=\"background: #ff4800;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td>&nbsp;</td>\r\n						<td>\r\n						<p style=\"color: #303030; font: 15px/20px Helvetica, Arial, sans-serif; margin: 25px 0 25px 0; text-align: center;\"><font style=\"vertical-align: inherit;\"><f