(7, 'General Escrow Instructions', 'a:2:{s:7:\"english\";s:146:\"<div class=\"header-st mb-4\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h3>&nbsp;</h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\";s:7:\"spanish\";s:0:\"\";}', '1'),
(8, 'Page not found', 'a:2:{s:7:\"english\";s:380:\"<div class=\"header-st mb-4\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h3>Page not founs</h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"container mt-5\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12 text-center\">\r\n<h3 class=\"mt-4\">This page has been deleted or does not exist</h3>\r\n\r\n<h1 class=\"mt-4\"><strong>404</strong></h1>\r\n</div>\r\n</div>\r\n</div>\";s:7:\"spanish\";s:397:\"<div class=\"header-st mb-4\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h3>P&aacute;gina no encontrada</h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"container mt-5\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12 text-center\">\r\n<h3 class=\"mt-4\">Esta p&aacute;gina ha sido eliminada o no existe</h3>\r\n\r\n<h1 class=\"mt-4\"><strong>404</strong></h1>\r\n</div>\r\n</div>\r\n</div>\";}', '1'),
(9, 'Verifica tu correo electrónico', 'a:2:{s:7:\"english\";s:827:\"<div class=\"header-st mb-4\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h3><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Verify your email</font></font></font></font></h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h4><strong><img alt=\"\" src=\"https://www.wavybeauty.com/img/mail_verify_icon.png\" style=\"width: 232px; height: 232px;\" />It will be necessary to verify your email to complete the registration.</strong></h4>\r\n\r\n<p>An email was sent to the Email used in the registration, with a link to verify the account. If you haven&#39;t received the email after a few minutes check the spam folder.</p>\r\n</div>\r\n</div>\r\n</div>\";s:7:\"spanish\";s:936:\"<div class=\"header-st mb-4\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h3><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">Verifica tu correo electr&oacute;nico</font></font></font></font></h3>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<h4><strong><img alt=\"\" src=\"https://www.wavybeauty.com/img/mail_verify_icon.png\" style=\"width: 232px; height: 232px;\" />Ser&aacute; necesario verificar tu correo electr&oacute;nico para completar el registro.</strong></h4>\r\n\r\n<p>Se envi&oacute; un correo electr&oacute;nico al Email utilizado en el registro&nbsp;con un enlace para verificar la cuenta. Si no has recibido el correo electr&oacute;nico despu&eacute;s de unos minutos verifica la carpeta de correo no deseado.</p>\r\n</div>\r\n</div>\r\n</div>\";}', '1');

